export class CancelError extends Error {
	constructor(reason) {
		super(reason || 'Promise was canceled');
		this.name = 'CancelError';
	}

	get isCanceled() {
		return true;
	}
}

const promiseState = Object.freeze({
	pending: Symbol('pending'),
	canceled: Symbol('canceled'),
	resolved: Symbol('resolved'),
	rejected: Symbol('rejected'),
});

export default class PCancelable {
	static fn(userFunction) {
		return (...arguments_) => new PCancelable((resolve, reject, onCancel) => {
			arguments_.push(onCancel);
			userFunction(...arguments_).then(resolve, reject);
		});
	}

	#cancelHandlers = [];
	#rejectOnCancel = true;
	#state = promiseState.pending;
	#promise;
	#reject;

	constructor(executor) {
		this.#promise = new Promise((resolve, reject) => {
			this.#reject = reject;

			const onResolve = value => {
				if (this.#state !== promiseState.canceled || !onCancel.shouldReject) {
					resolve(value);
					this.#setState(promiseState.resolved);
				}
			};

			const onReject = error => {
				if (this.#state !== promiseState.canceled || !onCancel.shouldReject) {
					reject(error);
					this.#setState(promiseState.rejected);
				}
			};

			const onCancel = handler => {
				if (this.#state !== promiseState.pending) {
					throw new Error(`The \`onCancel\` handler was attached after the promise ${this.#state.description}.`);
				}

				this.#cancelHandlers.push(handler);
			};

			Object.defineProperties(onCancel, {
				shouldReject: {
					get: () => this.#rejectOnCancel,
					set: boolean => {
						this.#rejectOnCancel = boolean;
					},
				},
			});

			executor(onResolve, onReject, onCancel);
		});
	}

	// eslint-disable-next-line unicorn/no-thenable
	then(onFulfilled, onRejected) {
		return this.#promise.then(onFulfilled, onRejected);
	}

	catch(onRejected) {
		return this.#promise.catch(onRejected);
	}

	finally(onFinally) {
		return this.#promise.finally(onFinally);
	}

	cancel(reason) {
		if (this.#state !== promiseState.pending) {
			return;
		}

		this.#setState(promiseState.canceled);

		if (this.#cancelHandlers.length > 0) {
			try {
				for (const handler of this.#cancelHandlers) {
					handler();
				}
			} catch (error) {
				this.#reject(error);
				return;
			}
		}

		if (this.#rejectOnCancel) {
			this.#reject(new CancelError(reason));
		}
	}

	get isCanceled() {
		return this.#state === promiseState.canceled;
	}

	#setState(state) {
		if (this.#state === promiseState.pending) {
			this.#state = state;
		}
	}
}

Object.setPrototypeOf(PCancelable.prototype, Promise.prototype);

import test from 'ava';
import delay from 'delay';
import PCancelable, {CancelError} from './index.js';

const fixture = Symbol('fixture');

test('new PCancelable()', async t => {
	t.plan(5);

	const cancelablePromise = new PCancelable((resolve, reject, onCancel) => {
		onCancel(() => {
			t.pass();
		});

		setTimeout(() => {
			resolve(fixture);
		}, 50);
	});

	t.true(cancelablePromise instanceof Promise);

	t.false(cancelablePromise.isCanceled);

	cancelablePromise.cancel();

	await t.throwsAsync(cancelablePromise, {instanceOf: CancelError});

	t.true(cancelablePromise.isCanceled);
});

test('calling `.cancel()` multiple times', async t => {
	t.plan(2);

	const cancelablePromise = new PCancelable((resolve, reject, onCancel) => {
		onCancel(() => {
			t.pass();
		});

		setTimeout(() => {
			resolve(fixture);
		}, 50);
	});

	cancelablePromise.cancel();
	cancelablePromise.cancel();

	try {
		await cancelablePromise;
	} catch (error) {
		cancelablePromise.cancel();
		t.true(error instanceof CancelError);
	}
});

test('no `.cancel()` call', async t => {
	const cancelablePromise = new PCancelable((resolve, reject, onCancel) => {
		onCancel(() => {
			t.fail();
		});

		setTimeout(() => {
			resolve(fixture);
		}, 50);
	});

	t.is(await cancelablePromise, fixture);
});

test('no `onCancel` handler', async t => {
	t.plan(1);

	const cancelablePromise = new PCancelable(resolve => {
		setTimeout(() => {
			resolve(fixture);
		}, 50);
	});

	cancelablePromise.cancel();

	await t.throwsAsync(cancelablePromise, {instanceOf: CancelError});
});

test('does not do anything when the promise is already settled', async t => {
	t.plan(2);

	const cancelablePromise = new PCancelable((resolve, reject, onCancel) => {
		onCancel(() => {
			t.fail();
		});

		resolve();
	});

	t.false(cancelablePromise.isCanceled);

	await cancelablePromise;

	cancelablePromise.cancel();

	t.false(cancelablePromise.isCanceled);
});

test('PCancelable.fn()', async t => {
	t.plan(2);

	const cancelableFunction = PCancelable.fn(async (input, onCancel) => {
		onCancel(() => {
			t.pass();
		});

		await delay(50);

		return input;
	});

	const cancelablePromise = cancelableFunction(fixture);

	cancelablePromise.cancel();

	await t.throwsAsync(cancelablePromise, {instanceOf: CancelError});
});

test('PCancelable.CancelError', t => {
	t.true(CancelError.prototype instanceof Error);
});

test('rejects when canceled', async t => {
	const cancelablePromise = new PCancelable((resolve, reject, onCancel) => {
		onCancel(() => {});
	});

	cancelablePromise.cancel();

	await t.throwsAsync(cancelablePromise, {instanceOf: CancelError});
});

test('rejects when canceled after a delay', async t => {
	const cancelablePromise = new PCancelable((resolve, reject, onCancel) => {
		onCancel(() => {});
	});

	setTimeout(() => {
		cancelablePromise.cancel();
	}, 100);

	await t.throwsAsync(cancelablePromise, {instanceOf: CancelError});
});

test('supports multiple `onCancel` handlers', async t => {
	let i = 0;

	const cancelablePromise = new PCancelable((resolve, reject, onCancel) => {
		onCancel(() => i++);
		onCancel(() => i++);
		onCancel(() => i++);
	});

	cancelablePromise.cancel();

	try {
		await cancelablePromise;
	} catch {}

	t.is(i, 3);
});

test('cancel error includes a `isCanceled` property', async t => {
	const cancelablePromise = new PCancelable(() => {});
	cancelablePromise.cancel();

	const error = await t.throwsAsync(cancelablePromise);
	t.true(error.isCanceled);
});

test('`onCancel` handler could not be attached after the promise resolved', async t => {
	const promiseState = 'resolved';
	const errorMessage = `The \`onCancel\` handler was attached after the promise ${promiseState}.`;

	// eslint-disable-next-line no-async-promise-executor
	const testPromise = new Promise(async testResolve => {
		const cancelablePromise = new PCancelable((resolve, reject, onCancel) => {
			resolve();

			setTimeout(() => {
				try {
					onCancel();
				} catch (error) {
					testResolve(error);
				}
			}, 0);
		});

		await cancelablePromise;
	});

	const {message} = await testPromise;
	t.is(message, errorMessage);
});

test('`onCancel` handler could not be attached after the promise rejected', async t => {
	const promiseState = 'rejected';
	const errorMessage = `The \`onCancel\` handler was attached after the promise ${promiseState}.`;

	// eslint-disable-next-line no-async-promise-executor
	const testPromise = new Promise(async testResolve => {
		const cancelablePromise = new PCancelable((resolve, reject, onCancel) => {
			reject(new Error('some error'));

			setTimeout(() => {
				try {
					onCancel();
				} catch (error) {
					testResolve(error);
				}
			}, 0);
		});

		await t.throwsAsync(cancelablePromise, {message: 'some error'});
	});

	const {message} = await testPromise;
	t.is(message, errorMessage);
});

test('`onCancel` handler could not be attached after the promise canceled', async t => {
	const promiseState = 'canceled';
	const errorMessage = `The \`onCancel\` handler was attached after the promise ${promiseState}.`;

	// eslint-disable-next-line no-async-promise-executor
	const testPromise = new Promise(async testResolve => {
		const cancelablePromise = new PCancelable((resolve, reject, onCancel) => {
			onCancel.shouldReject = false;

			setTimeout(() => {
				try {
					onCancel();
				} catch (error) {
					testResolve(error);
				}
			}, 0);
		});

		cancelablePromise.cancel();

		await cancelablePromise;
	});

	const {message} = await testPromise;
	t.is(message, errorMessage);
});

test('supports `finally`', async t => {
	const cancelablePromise = new PCancelable(async resolve => {
		await delay(1);
		resolve();
	});

	t.plan(1);

	try {
		await cancelablePromise;
	} finally {
		t.pass();
	}
});

test('default message with no reason', async t => {
	const cancelablePromise = new PCancelable(() => {});
	cancelablePromise.cancel();

	await t.throwsAsync(cancelablePromise, {message: 'Promise was canceled'});
});

test('custom reason', async t => {
	const cancelablePromise = new PCancelable(() => {});
	cancelablePromise.cancel('unicorn');

	await t.throwsAsync(cancelablePromise, {message: 'unicorn'});
});

test('prevent rejection', async t => {
	const cancelablePromise = new PCancelable((resolve, reject, onCancel) => {
		onCancel.shouldReject = false;
		setTimeout(resolve, 100);
	});

	cancelablePromise.cancel();
	await t.notThrowsAsync(cancelablePromise);
	// `cancelablePromise` is canceled before cancelablePromise resolved.
	t.true(cancelablePromise.isCanceled);
});

test('prevent rejection and reject later', async t => {
	const cancelablePromise = new PCancelable((resolve, reject, onCancel) => {
		onCancel.shouldReject = false;
		setTimeout(() => reject(new Error('unicorn')), 100);
	});

	cancelablePromise.cancel();
	await t.throwsAsync(cancelablePromise, {message: 'unicorn'});
	// `cancelablePromise` is canceled before cancelablePromise rejected with unicorn Error.
	t.true(cancelablePromise.isCanceled);
});

test('prevent rejection and resolve later', async t => {
	const cancelablePromise = new PCancelable((resolve, reject, onCancel) => {
		onCancel.shouldReject = false;
		setTimeout(() => resolve('unicorn'), 100);
	});

	t.is(await cancelablePromise, 'unicorn');
});

test('`onCancel.shouldReject` is true by default', async t => {
	await t.notThrows(() => new PCancelable((resolve, reject, onCancel) => {
		t.true(onCancel.shouldReject);
	}));
});

test('throws on cancel when `onCancel.shouldReject` is true', async t => {
	const cancelablePromise = new PCancelable((resolve, reject, onCancel) => {
		onCancel.shouldReject = false;
		onCancel.shouldReject = true;
	});
	cancelablePromise.cancel();

	await t.throwsAsync(cancelablePromise);
});

test('throws immediately as soon as .cancel() is called', async t => {
	const cancelablePromise = new PCancelable((resolve, reject, onCancel) => {
		const timeout = setTimeout(() => {
			resolve(true);
		}, 10);

		onCancel.shouldReject = true;
		onCancel(() => {
			clearTimeout(timeout);
			resolve(false);
		});
	});

	cancelablePromise.cancel();

	await t.throwsAsync(cancelablePromise, {
		message: 'Promise was canceled',
	});
});

/**
The rejection reason when `.cancel()` is called.

It includes a `.isCanceled` property for convenience.
*/
export class CancelError extends Error {
	readonly name: 'CancelError';
	readonly isCanceled: true;

	constructor(reason?: string);
}

/**
Accepts a function that is called when the promise is canceled.

You're not required to call this function. You can call this function multiple times to add multiple cancel handlers.
*/
export interface OnCancelFunction {
	(cancelHandler: () => void): void;
	shouldReject: boolean;
}

// eslint-disable-next-line @typescript-eslint/naming-convention
export default class PCancelable<ValueType> extends Promise<ValueType> {
	/**
	Convenience method to make your promise-returning or async function cancelable.

	@param fn - A promise-returning function. The function you specify will have `onCancel` appended to its parameters.

	@example
	```
	import PCancelable from 'p-cancelable';

	const fn = PCancelable.fn((input, onCancel) => {
		const job = new Job();

		onCancel(() => {
			job.cleanup();
		});

		return job.start(); //=> Promise
	});

	const cancelablePromise = fn('input'); //=> PCancelable

	// …

	cancelablePromise.cancel();
	```
	*/
	static fn<ReturnType>(
		userFn: (onCancel: OnCancelFunction) => PromiseLike<ReturnType>
	): () => PCancelable<ReturnType>;
	static fn<Agument1Type, ReturnType>(
		userFn: (
			argument1: Agument1Type,
			onCancel: OnCancelFunction
		) => PromiseLike<ReturnType>
	): (argument1: Agument1Type) => PCancelable<ReturnType>;
	static fn<Agument1Type, Agument2Type, ReturnType>(
		userFn: (
			argument1: Agument1Type,
			argument2: Agument2Type,
			onCancel: OnCancelFunction
		) => PromiseLike<ReturnType>
	): (
		argument1: Agument1Type,
		argument2: Agument2Type
	) => PCancelable<ReturnType>;
	static fn<Agument1Type, Agument2Type, Agument3Type, ReturnType>(
		userFn: (
			argument1: Agument1Type,
			argument2: Agument2Type,
			argument3: Agument3Type,
			onCancel: OnCancelFunction
		) => PromiseLike<ReturnType>
	): (
		argument1: Agument1Type,
		argument2: Agument2Type,
		argument3: Agument3Type
	) => PCancelable<ReturnType>;
	static fn<Agument1Type, Agument2Type, Agument3Type, Agument4Type, ReturnType>(
		userFn: (
			argument1: Agument1Type,
			argument2: Agument2Type,
			argument3: Agument3Type,
			argument4: Agument4Type,
			onCancel: OnCancelFunction
		) => PromiseLike<ReturnType>
	): (
		argument1: Agument1Type,
		argument2: Agument2Type,
		argument3: Agument3Type,
		argument4: Agument4Type
	) => PCancelable<ReturnType>;
	static fn<
		Agument1Type,
		Agument2Type,
		Agument3Type,
		Agument4Type,
		Agument5Type,
		ReturnType,
	>(
		userFn: (
			argument1: Agument1Type,
			argument2: Agument2Type,
			argument3: Agument3Type,
			argument4: Agument4Type,
			argument5: Agument5Type,
			onCancel: OnCancelFunction
		) => PromiseLike<ReturnType>
	): (
		argument1: Agument1Type,
		argument2: Agument2Type,
		argument3: Agument3Type,
		argument4: Agument4Type,
		argument5: Agument5Type
	) => PCancelable<ReturnType>;
	static fn<ReturnType>(
		userFn: (...arguments: unknown[]) => PromiseLike<ReturnType>
	): (...arguments: unknown[]) => PCancelable<ReturnType>;

	/**
	Whether the promise is canceled.
	*/
	readonly isCanceled: boolean;

	/**
	Cancel the promise and optionally provide a reason.

	The cancellation is synchronous. Calling it after the promise has settled or multiple times does nothing.

	@param reason - The cancellation reason to reject the promise with.
	*/
	cancel: (reason?: string) => void;

	/**
	Create a promise that can be canceled.

	Can be constructed in the same was as a [`Promise` constructor](https://developer.mozilla.org/en/docs/Web/JavaScript/Reference/Global_Objects/Promise), but with an appended `onCancel` parameter in `executor`. `PCancelable` is a subclass of `Promise`.

	Cancelling will reject the promise with `CancelError`. To avoid that, set `onCancel.shouldReject` to `false`.

	@example
	```
	import PCancelable from 'p-cancelable';

	const cancelablePromise = new PCancelable((resolve, reject, onCancel) => {
		const job = new Job();

		onCancel.shouldReject = false;
		onCancel(() => {
			job.stop();
		});

		job.on('finish', resolve);
	});

	cancelablePromise.cancel(); // Doesn't throw an error
	```
	*/
	constructor(
		executor: (
			resolve: (value?: ValueType | PromiseLike<ValueType>) => void,
			reject: (reason?: unknown) => void,
			onCancel: OnCancelFunction
		) => void
	);
}

export class TimeoutError extends Error {
	name = 'TimeoutError';

	constructor(message, options) {
		super(message, options);
		// V8-only, and it does exactly one thing here: it hides this constructor frame from the stack.
		// eslint-disable-next-line unicorn/no-useless-error-capture-stack-trace, unicorn/no-nonstandard-builtin-properties
		Error.captureStackTrace?.(this, TimeoutError);
	}
}

// An `AbortSignal` always has a reason once aborted, and that reason is whatever the caller passed to `abort()`, including `null`. Only hand-rolled signal objects can lack the property entirely.
const getAbortedReason = signal => 'reason' in signal
	? signal.reason
	: new DOMException('This operation was aborted.', 'AbortError');

// `setTimeout` stores its delay in a 32-bit signed integer, so this is the largest delay it can represent.
const maximumDelay = (2 ** 31) - 1;

const getOptionsError = (milliseconds, customTimers) => {
	if (typeof milliseconds !== 'number' || Math.sign(milliseconds) !== 1) {
		return new TypeError(`Expected \`milliseconds\` to be a positive number, got \`${milliseconds}\``);
	}

	if (typeof customTimers?.setTimeout !== 'function' || typeof customTimers?.clearTimeout !== 'function') {
		return new TypeError('Expected `customTimers` to have a `setTimeout` and a `clearTimeout` function');
	}
};

export default function pTimeout(promise, options) {
	const {
		milliseconds,
		fallback,
		message,
		customTimers = {setTimeout, clearTimeout},
		signal,
	} = options;

	let timer;
	let abortHandler;

	// Best-effort cancellation of the input, so a throwing `.cancel()` can neither escape the timer callback as an uncaught exception nor prevent us from settling. Anything that is not callable is skipped by the same `try`. It always runs after the outcome is decided, as `.cancel()` may settle the input synchronously through the handlers we passed to `then`.
	const cancelInput = () => {
		try {
			promise.cancel?.();
		} catch {
			// Ignored: the outcome matters more than a failure to stop the work early.
		}
	};

	const wrappedPromise = new Promise((resolve, reject) => {
		const abort = () => {
			reject(getAbortedReason(signal));
			// The caller no longer wants the result, so stop the underlying work, the same as a timeout does.
			cancelInput();
		};

		// `input` is a `PromiseLike`, so it may settle during the call to `then`. Anything that has to win over its outcome, an invalid option or an abort the caller already committed to, is therefore decided before it is attached. Otherwise a synchronous thenable settles the wrapper first and buries both.
		const optionsError = getOptionsError(milliseconds, customTimers);
		const isAborted = !optionsError && signal?.aborted;

		if (optionsError) {
			reject(optionsError);
		} else if (isAborted) {
			abort();
		}

		// Use .then() instead of async IIFE to preserve stack traces. This also observes the input when it has already lost, so its rejection cannot escape as an unhandled rejection that crashes the process and hides the real error. It has to be the only handler on the input, as an extra one costs the input's rejection its caller frames in the stack trace.
		// eslint-disable-next-line unicorn/prefer-then-catch
		promise.then(resolve, reject);

		if (optionsError || isAborted) {
			return;
		}

		if (signal) {
			abortHandler = abort;
			signal.addEventListener('abort', abortHandler, {once: true});
		}

		// A delay that `setTimeout` cannot represent never elapses, so there is nothing to time out. Without this, `setTimeout` silently clamps anything above 2 ** 31 - 1 to 1ms and the timeout fires at once.
		if (milliseconds > maximumDelay) {
			return;
		}

		// We create the error outside of `setTimeout` to preserve the stack trace, but only when the timeout can actually reject with it, since capturing a stack trace is expensive and most promises settle first.
		const timeoutError = fallback || message === false || message instanceof Error
			? undefined
			: new TimeoutError(message ?? `Promise timed out after ${milliseconds} milliseconds`);

		// `.call(undefined, ...)` is needed for custom timers to avoid context issues
		timer = customTimers.setTimeout.call(undefined, () => {
			if (fallback) {
				try {
					resolve(fallback());
				} catch (error) {
					reject(error);
				}
			} else if (message === false) {
				resolve();
			} else {
				reject(message instanceof Error ? message : timeoutError);
			}

			// The input timed out even when a fallback takes over, and the readme promises `.cancel()` runs on timeout.
			cancelInput();
		}, milliseconds);
	});

	const cancelablePromise = wrappedPromise.finally(() => {
		// The outcome is already decided, so a failing cleanup step must neither change it nor stop the other step: a `clearTimeout` that throws must not leave the abort listener attached.
		try {
			cancelablePromise.clear();
		} catch {
			// Ignored. The timer handle is deliberately left in place so an explicit `clear()` can still retry.
		}

		try {
			if (abortHandler) {
				signal.removeEventListener('abort', abortHandler);
			}
		} catch {
			// Ignored, for the same reason.
		}
	});

	cancelablePromise.clear = () => {
		// A timeout that never elapses creates no timer, and a custom `clearTimeout` is entitled to reject `undefined`.
		if (timer === undefined) {
			return;
		}

		// `.call(undefined, ...)` is needed for custom timers to avoid context issues
		customTimers.clearTimeout.call(undefined, timer);
		timer = undefined;
	};

	return cancelablePromise;
}

import process from 'node:process';
import {execFile} from 'node:child_process';
import {promisify} from 'node:util';
import {test} from 'node:test';
import assert from 'node:assert/strict';
import delay from 'delay';
import PCancelable from 'p-cancelable';
import inRange from 'in-range';
import timeSpan from 'time-span';
import sinon from 'sinon';
import pTimeout, {TimeoutError} from './index.js';

const fixture = Symbol('fixture');
const fixtureError = new Error('fixture');

const captureRejection = async promise => {
	try {
		await promise;
	} catch (error) {
		return error;
	}

	return undefined;
};

const settleOutcome = async promise => {
	try {
		await promise;
		return 'resolved';
	} catch {
		return 'rejected';
	}
};

// Reports how a promise settled, or that it was still pending after `milliseconds`.
const settleWithin = (promise, milliseconds) => Promise.race([
	settleOutcome(promise),
	delay(milliseconds, {value: 'still pending'}),
]);

// A never-settling promise with a `.cancel()` method. `p-cancelable` cannot be used to test a throwing `.cancel()`, since it catches handler errors and rejects itself rather than letting them escape.
const createCancelable = cancel => {
	const promise = new Promise(() => {});
	promise.cancel = cancel;
	return promise;
};

const throwingClearTimers = {
	setTimeout,
	clearTimeout() {
		throw new Error('`clearTimeout` blew up');
	},
};

// Real timers that record every call, so a test can see exactly what p-timeout asked for.
const createRecordingTimers = () => {
	const calls = {setTimeout: [], clearTimeout: []};
	const customTimers = {
		setTimeout(callback, milliseconds) {
			calls.setTimeout.push(milliseconds);
			return setTimeout(callback, milliseconds);
		},
		clearTimeout(timer) {
			calls.clearTimeout.push(timer);
			clearTimeout(timer);
		},
	};

	return {calls, customTimers};
};

// A synchronous thenable, which the declared `PromiseLike` input type allows. It settles during the call to `then`, so anything that relies on the input settling in a microtask is bypassed.
const createSyncThenable = settle => ({
	// eslint-disable-next-line unicorn/no-thenable -- being a thenable is the entire point
	then(onFulfilled, onRejected) {
		settle(onFulfilled, onRejected);
	},
});

// Runs `code` with p-timeout in a child process that crashes on any unhandled rejection. The output is `handled` only when it got to the end.
const runWithStrictUnhandledRejections = async code => {
	const {stdout} = await promisify(execFile)(process.execPath, [
		'--unhandled-rejections=strict',
		'--input-type=module',
		'--eval',
		`
			import assert from 'node:assert/strict';
			import pTimeout from ${JSON.stringify(new URL('index.js', import.meta.url).href)};
			${code}
			await new Promise(resolve => setTimeout(resolve, 100));
